             tisd_D_CK : VitalDelayType := DefDummyIsd;
             tipd_RN : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_RN_CK : VitalDelayType := DefDummyIsd;
             tipd_SN : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_SN_CK : VitalDelayType := DefDummyIsd;
             trecovery_SN_CK_posedge_posedge : VitalDelayType := 0.0187502 ns;
             tremoval_SN_CK_posedge_posedge : VitalDelayType := 0.03125 ns;
             trecovery_RN_SN_posedge_posedge : VitalDelayType := 0.08125 ns;
             trecovery_RN_CK_posedge_posedge : VitalDelayType := 0.06875 ns;
