             tpw_CK_posedge : VitalDelayType := 0.207455 ns;
             tpw_CK_negedge : VitalDelayType := 0.125285 ns;
             tpw_RN_negedge : VitalDelayType := 0.240917 ns;
             tpw_SN_negedge : VitalDelayType := 0.183259 ns;
             tsetup_D_CK_posedge_posedge : VitalDelayType := 0.08125 ns;
             tsetup_D_CK_negedge_posedge : VitalDelayType := 0.0500002 ns;
             thold_D_CK_posedge_posedge : VitalDelayType := -0.0187501 ns;
             thold_D_CK_negedge_posedge : VitalDelayType := 0.0187503 ns;
