             tpd_SN_Q_posedge : VitalDelayType01 := (0 ns, 0.209991 ns);
             tpd_SN_QN_negedge : VitalDelayType01 := (0 ns, 0.181773 ns);
             tpd_SN_QN_posedge : VitalDelayType01 := (0.220197 ns, 0 ns);

             TimingChecksOn : BOOLEAN := false;
