             tsetup_RN_CK_posedge_posedge : VitalDelayType := 0.0749999 ns;
             tsetup_RN_CK_negedge_posedge : VitalDelayType := 0.0250001 ns;
             thold_RN_CK_posedge_posedge : VitalDelayType := -0.0437501 ns;
             thold_RN_CK_negedge_posedge : VitalDelayType := 0.00625004 ns;
             tsetup_D_CK_posedge_posedge : VitalDelayType := 0.0750001 ns;
             tsetup_D_CK_negedge_posedge : VitalDelayType := 0.0249999 ns;
             thold_D_CK_posedge_posedge : VitalDelayType := -0.04375 ns;
             thold_D_CK_negedge_posedge : VitalDelayType := 0.00625006 ns;
             tpd_CK_Q_posedge : VitalDelayType01 := (0.12018 ns, 0.135087 ns);
             tpd_CK_QN_posedge : VitalDelayType01 := (0.157165 ns, 0.14504 ns);

             TimingChecksOn : BOOLEAN := false;
             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         CK : in std_ulogic := 'U' ;
         D : in std_ulogic := 'U' ;
