             trecovery_RN_SN_posedge_posedge : VitalDelayType := 0.0812501 ns;
             trecovery_RN_CKN_posedge_negedge : VitalDelayType := 0.0375001 ns;
             tremoval_RN_CKN_posedge_negedge : VitalDelayType := -0.0000000000552102 ns;
             tpw_CKN_posedge : VitalDelayType := 0.109924 ns;
             tpw_CKN_negedge : VitalDelayType := 0.191405 ns;
             tpw_RN_negedge : VitalDelayType := 0.238427 ns;
             tpw_SN_negedge : VitalDelayType := 0.182692 ns;
             tsetup_SI_CKN_posedge_negedge : VitalDelayType := 0.09375 ns;
