             tsetup_SE_CKN_posedge_negedge : VitalDelayType := 0.125 ns;
             tsetup_SE_CKN_negedge_negedge : VitalDelayType := 0.1125 ns;
             thold_SE_CKN_posedge_negedge : VitalDelayType := -0.0124999 ns;
             thold_SE_CKN_negedge_negedge : VitalDelayType := -0.03125 ns;
             tsetup_D_CKN_posedge_negedge : VitalDelayType := 0.0937503 ns;
             tsetup_D_CKN_negedge_negedge : VitalDelayType := 0.11875 ns;
             thold_D_CKN_posedge_negedge : VitalDelayType := -0.0187503 ns;
             thold_D_CKN_negedge_negedge : VitalDelayType := -0.0625001 ns;
             tremoval_RN_SN_posedge_posedge : VitalDelayType := VitalZeroDelay;
             tpd_CKN_Q_negedge : VitalDelayType01 := (0.200361 ns, 0.182094 ns);
             tpd_CKN_QN_negedge : VitalDelayType01 := (0.191402 ns, 0.20775 ns);
             tpd_RN_Q_negedge : VitalDelayType01 := (0 ns, 0.225191 ns);
             tpd_RN_QN_negedge : VitalDelayType01 := (0.234681 ns, 0 ns);
             tpd_SN_Q_negedge : VitalDelayType01 := (0.172402 ns, 0 ns);
             tpd_SN_Q_posedge : VitalDelayType01 := (0 ns, 0.209094 ns);
             tpd_SN_QN_negedge : VitalDelayType01 := (0 ns, 0.180425 ns);
