             tpw_CK_posedge : VitalDelayType := 0.144498 ns;
             tpw_CK_negedge : VitalDelayType := 0.0903848 ns;
             tsetup_SI_CK_posedge_posedge : VitalDelayType := 0.0812502 ns;
