             tpd_RN_Q_negedge : VitalDelayType01 := (0 ns, 0.0625427 ns);
             tpd_RN_QN_negedge : VitalDelayType01 := (0.0845532 ns, 0 ns);

             TimingChecksOn : BOOLEAN := false;
             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
