             thold_SI_CK_posedge_posedge : VitalDelayType := -0.0562499 ns;
             thold_SI_CK_negedge_posedge : VitalDelayType := -0.0125 ns;
             tsetup_SE_CK_posedge_posedge : VitalDelayType := 0.0812503 ns;
             tsetup_SE_CK_negedge_posedge : VitalDelayType := 0.0999998 ns;
             thold_SE_CK_posedge_posedge : VitalDelayType := -0.0187503 ns;
