             tpw_CK_posedge : VitalDelayType := 0.201204 ns;
             tpw_CK_negedge : VitalDelayType := 0.112053 ns;
             tpw_SN_negedge : VitalDelayType := 0.174614 ns;
             tsetup_SI_CK_posedge_posedge : VitalDelayType := 0.0875 ns;
             tsetup_SI_CK_negedge_posedge : VitalDelayType := 0.09375 ns;
             thold_SI_CK_posedge_posedge : VitalDelayType := -0.0562499 ns;
             thold_SI_CK_negedge_posedge : VitalDelayType := -0.0187502 ns;
             tsetup_SE_CK_posedge_posedge : VitalDelayType := 0.0999999 ns;
             tsetup_SE_CK_negedge_posedge : VitalDelayType := 0.0999999 ns;
             thold_SE_CK_posedge_posedge : VitalDelayType := -0.0249999 ns;
             thold_SE_CK_negedge_posedge : VitalDelayType := -0.0125 ns;
             tsetup_D_CK_posedge_posedge : VitalDelayType := 0.0937501 ns;
             tsetup_D_CK_negedge_posedge : VitalDelayType := 0.09375 ns;
             thold_D_CK_posedge_posedge : VitalDelayType := -0.05625 ns;
