             thold_SI_CK_posedge_posedge : VitalDelayType := -0.0625 ns;
             thold_SI_CK_negedge_posedge : VitalDelayType := -0.0250002 ns;
             tsetup_SE_CK_posedge_posedge : VitalDelayType := 0.0875002 ns;
             thold_SE_CK_negedge_posedge : VitalDelayType := -0.0249997 ns;
             tsetup_SE_CK_negedge_posedge : VitalDelayType := 0.1125 ns;
             thold_SE_CK_posedge_posedge : VitalDelayType := -0.0375 ns;
             tsetup_E_CK_posedge_posedge : VitalDelayType := 0.15 ns;
             tsetup_E_CK_negedge_posedge : VitalDelayType := 0.13125 ns;
             thold_E_CK_posedge_posedge : VitalDelayType := -0.11875 ns;
