             tipd_SN : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_SN_RN : VitalDelayType := DefDummyIsd;
             trecovery_SN_RN_posedge_posedge : VitalDelayType := 0.0187498 ns;
             tremoval_SN_RN_posedge_posedge : VitalDelayType := 0.0125 ns;
             trecovery_SN_GN_posedge_posedge : VitalDelayType := -0.0062498 ns;
             tremoval_SN_GN_posedge_posedge : VitalDelayType := 0.0375001 ns;
             tpw_GN_negedge : VitalDelayType := 0.196822 ns;
             tpw_RN_negedge : VitalDelayType := 0.149745 ns;
             tpw_SN_negedge : VitalDelayType := 0.101896 ns;
             tsetup_RN_GN_posedge_posedge : VitalDelayType := 0.0875001 ns;
             thold_RN_GN_posedge_posedge : VitalDelayType := -0.0749998 ns;
             tsetup_D_GN_posedge_posedge : VitalDelayType := 0.0312503 ns;
             tsetup_D_GN_negedge_posedge : VitalDelayType := 0.0562498 ns;
             thold_D_GN_posedge_posedge : VitalDelayType := -0.0124999 ns;
             thold_D_GN_negedge_posedge : VitalDelayType := -0.0312499 ns;
             tpd_D_Q : VitalDelayType01 := (0.118614 ns, 0.142041 ns);
             tpd_D_QN : VitalDelayType01 := (0.134272 ns, 0.110142 ns);
             tpd_GN_Q_negedge : VitalDelayType01 := (0.187079 ns, 0.196822 ns);
             tpd_GN_QN_negedge : VitalDelayType01 := (0.189096 ns, 0.17858 ns);
