             tpd_SN_Q_negedge : VitalDelayType01 := (0.0619698 ns, 0 ns);
             tpd_SN_Q_posedge : VitalDelayType01 := (0 ns, 0.0865241 ns);
             tpd_SN_QN_negedge : VitalDelayType01 := (0 ns, 0.053304 ns);
