             thold_SE_CK_posedge_posedge : VitalDelayType := -0.0374998 ns;
             thold_SE_CK_negedge_posedge : VitalDelayType := -0.0437499 ns;
             tsetup_E_CK_posedge_posedge : VitalDelayType := 0.0437499 ns;
             tsetup_E_CK_negedge_posedge : VitalDelayType := 0.0500001 ns;
             thold_E_CK_posedge_posedge : VitalDelayType := -0.0374999 ns;
             thold_E_CK_negedge_posedge : VitalDelayType := -0.04375 ns;
             tpd_CK_ECK_negedge : VitalDelayType01 := (0 ns, 0.0978083 ns);
             tpd_CK_ECK_posedge : VitalDelayType01 := (0.112645 ns, 0 ns);

             TimingChecksOn : BOOLEAN := false;
             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         CK : in std_ulogic := 'U' ;
         E : in std_ulogic := 'U' ;
         SE : in std_ulogic := 'U' ;
         ECK : out std_ulogic);

