             tipd_S0 : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tisd_S0_CK : VitalDelayType := DefDummyIsd;
             tpw_CK_posedge : VitalDelayType := 0.146949 ns;
             tpw_CK_negedge : VitalDelayType := 0.0939124 ns;
             tsetup_S0_CK_posedge_posedge : VitalDelayType := 0.0624998 ns;
             tsetup_S0_CK_negedge_posedge : VitalDelayType := 0.0812499 ns;
             thold_S0_CK_posedge_posedge : VitalDelayType := -0.01875 ns;
             thold_S0_CK_negedge_posedge : VitalDelayType := -0.0000000000993336 ns;
