begin

--Input Path Delays
WIREDELAY : BLOCK
BEGIN
   VitalWireDelay( CK_ipd, CK, tipd_CK );
   VitalWireDelay( D0_ipd, D0, tipd_D0 );
   VitalWireDelay( D1_ipd, D1, tipd_D1 );
   VitalWireDelay( S0_ipd, S0, tipd_S0 );
END BLOCK;

SIGNALDELAY : BLOCK
BEGIN
   VitalSignalDelay( CK_dly, CK_ipd, ticd_CK );
   VitalSignalDelay( D0_dly, D0_ipd, tisd_D0_CK );
   VitalSignalDelay( D1_dly, D1_ipd, tisd_D1_CK );
   VitalSignalDelay( S0_dly, S0_ipd, tisd_S0_CK );
END BLOCK;

VITALBehavior : PROCESS (CK_dly, D0_dly, D1_dly, S0_dly)

      --timing checks section variables
      VARIABLE Tviol_S0_CK : std_ulogic := '0';
      VARIABLE TimeMarker_S0_CK : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE Tviol_D1_CK : std_ulogic := '0';
      VARIABLE TimeMarker_D1_CK : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE Tviol_D0_CK : std_ulogic := '0';
      VARIABLE TimeMarker_D0_CK : VitalTimingDataType := VitalTimingDataInit;
      VARIABLE PWviol_CK : std_ulogic := '0';
      VARIABLE PeriodCheckInfo_CK : VitalPeriodDataType;

      -- functionality section variables
      VARIABLE n0_D : std_ulogic;
      VARIABLE intclk : std_ulogic;
      VARIABLE n0_RN_dly : std_ulogic := '0';
      VARIABLE n0_SN_dly : std_ulogic := '0';
      VARIABLE N30 : std_ulogic;
      VARIABLE QBINT : std_ulogic;
      VARIABLE n0_vec : std_logic_vector( 1 TO 1 );
      VARIABLE PrevData_udp_dff_n0 : std_logic_vector( 0 TO 4 );
      VARIABLE Q_zd : std_ulogic;
      VARIABLE n1_var : std_ulogic;
      VARIABLE D0_EQ_0_AN_D1_EQ_1 : std_ulogic;
      VARIABLE n2_var : std_ulogic;
      VARIABLE D0_EQ_1_AN_D1_EQ_0 : std_ulogic;
      VARIABLE S0_EQ_1 : std_ulogic;
      VARIABLE S0_EQ_0 : std_ulogic;
      VARIABLE n3_var : std_ulogic;
      VARIABLE n4_var : std_ulogic;
      VARIABLE n5_var : std_ulogic;
      VARIABLE n6_var : std_ulogic;
      VARIABLE D0_EQ_0_AN_D1_EQ_0_AN_S0_EQ_0 : std_ulogic;
      VARIABLE NOTIFIER : std_ulogic := '0';

      -- path delay section variables
      VARIABLE Q_GlitchData : VitalGlitchDataType;

      BEGIN
          -- Timing checks section
          IF (TimingChecksOn) THEN

                VitalSetupHoldCheck (
                    TestSignal     => S0_dly,
                    TestSignalName => "S0",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_S0_CK_posedge_posedge,
                    SetupLow       => tsetup_S0_CK_negedge_posedge,
                    HoldHigh       => thold_S0_CK_posedge_posedge,
                    HoldLow        => thold_S0_CK_negedge_posedge,
                    CheckEnabled   => To_X01(D0_EQ_0_AN_D1_EQ_1) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/MDFFHQX1",
                    TimingData     => TimeMarker_S0_CK,
                    Violation      => Tviol_S0_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalSetupHoldCheck (
                    TestSignal     => D1_dly,
                    TestSignalName => "D1",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_D1_CK_posedge_posedge,
                    SetupLow       => tsetup_D1_CK_negedge_posedge,
                    HoldHigh       => thold_D1_CK_posedge_posedge,
                    HoldLow        => thold_D1_CK_negedge_posedge,
                    CheckEnabled   => To_X01(S0_EQ_1) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/MDFFHQX1",
                    TimingData     => TimeMarker_D1_CK,
                    Violation      => Tviol_D1_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalSetupHoldCheck (
                    TestSignal     => D0_dly,
                    TestSignalName => "D0",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_D0_CK_posedge_posedge,
                    SetupLow       => tsetup_D0_CK_negedge_posedge,
                    HoldHigh       => thold_D0_CK_posedge_posedge,
                    HoldLow        => thold_D0_CK_negedge_posedge,
                    CheckEnabled   => To_X01(S0_EQ_0) /= '0',
                    RefTransition  => 'R',
                    HeaderMsg      => InstancePath & "/MDFFHQX1",
                    TimingData     => TimeMarker_D0_CK,
                    Violation      => Tviol_D0_CK,
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalPeriodPulseCheck (
                    TestSignal     => CK_dly,
                    TestSignalName => "CK",
                    Period         => 0 ps,
                    PulseWidthHigh => tpw_CK_posedge,
                    PulseWidthLow  => tpw_CK_negedge,
                    PeriodData     => PeriodCheckInfo_CK,
                    Violation      => PWviol_CK,
                    HeaderMsg      => InstancePath & "/MDFFHQX1",
                    CheckEnabled   => To_X01(D0_EQ_0_AN_D1_EQ_0_AN_S0_EQ_0) /= '0',
                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

          END IF;


          -- Functionality section
          NOTIFIER := (
                        Tviol_S0_CK OR
                        Tviol_D1_CK OR
                        Tviol_D0_CK OR
                        PWviol_CK );

          n0_D := VitalMUX2(D1_dly, D0_dly, S0_dly);

          intclk := VitalBUF(CK_dly);

          n0_RN_dly := '0';

          n0_SN_dly := '0';

          VitalStateTable ( StateTable => udp_dff,
                                DataIn => (NOTIFIER, n0_D, intclk, n0_RN_dly, n0_SN_dly),
