             thold_SI_CK_negedge_posedge : VitalDelayType := -0.0125002 ns;
             tsetup_SE_CK_posedge_posedge : VitalDelayType := 0.0812502 ns;
             tsetup_SE_CK_negedge_posedge : VitalDelayType := 0.1 ns;
             thold_SE_CK_posedge_posedge : VitalDelayType := -0.025 ns;
             thold_SE_CK_negedge_posedge : VitalDelayType := -0.00624997 ns;
             tsetup_D_CK_posedge_posedge : VitalDelayType := 0.0875002 ns;
             tsetup_D_CK_negedge_posedge : VitalDelayType := 0.0625 ns;
             thold_D_CK_posedge_posedge : VitalDelayType := -0.0499998 ns;
             thold_D_CK_negedge_posedge : VitalDelayType := -0.0125 ns;
             tpd_CK_Q_posedge : VitalDelayType01 := (0.119019 ns, 0.134486 ns);
