             tpd_A_Y : VitalDelayType01 := (0.0467092 ns, 0.0410203 ns);
             tpd_OE_Y : VitalDelayType01Z := (VitalZeroDelay, VitalZeroDelay, 0.0450468 ns, 0.0439204 ns, 0.0248621 ns, 0.059585 ns);

             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

