entity XNOR3X1 is
   generic (
             tipd_A : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tipd_B : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tipd_C : VitalDelayType01 := (DefDummyIpd, DefDummyIpd);
             tpd_A_Y_posedge : VitalDelayType01 := (0.145981 ns, 0.196725 ns);
             tpd_A_Y_negedge : VitalDelayType01 := (0.178994 ns, 0.144961 ns);
             tpd_B_Y_posedge : VitalDelayType01 := (0.12879 ns, 0.14253 ns);
             tpd_B_Y_negedge : VitalDelayType01 := (0.132147 ns, 0.13515 ns);
             tpd_C_Y_posedge : VitalDelayType01 := (0.0887181 ns, 0.107396 ns);
             tpd_C_Y_negedge : VitalDelayType01 := (0.0955156 ns, 0.100344 ns);

             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         A : in std_ulogic := 'U' ;
         B : in std_ulogic := 'U' ;
         C : in std_ulogic := 'U' ;
         Y : out std_ulogic);

   attribute VITAL_LEVEL0 of XNOR3X1 : entity is TRUE;
end XNOR3X1;

architecture behavioral of XNOR3X1 is
   attribute VITAL_LEVEL1 of behavioral : architecture is TRUE;

   SIGNAL A_ipd : std_ulogic := 'X';
   SIGNAL B_ipd : std_ulogic := 'X';
   SIGNAL C_ipd : std_ulogic := 'X';

begin

--Input Path Delays
WIREDELAY : BLOCK
BEGIN
   VitalWireDelay( A_ipd, A, tipd_A );
   VitalWireDelay( B_ipd, B, tipd_B );
   VitalWireDelay( C_ipd, C, tipd_C );
END BLOCK;

VITALBehavior : PROCESS (A_ipd, B_ipd, C_ipd)


      -- functionality section variables
      VARIABLE n0_var : std_ulogic;
      VARIABLE n1_var : std_ulogic;
      VARIABLE Y_zd : std_ulogic;

      -- path delay section variables
      VARIABLE Y_GlitchData : VitalGlitchDataType;

      BEGIN
          -- Functionality section
          n0_var := VitalXOR2(A_ipd, B_ipd);
          n1_var := VitalXOR2(n0_var, C_ipd);
          Y_zd := VitalINV(n1_var);


          -- Path delay section
          VitalPathDelay01(
               OutSignal     => Y,
               OutSignalName => "Y",
               OutTemp => Y_zd,
               Paths => (
                      0 => ( A_ipd'LAST_EVENT,
                             tpd_A_Y_posedge,
                             To_X01(A_ipd) /= '1'),
                      1 => ( A_ipd'LAST_EVENT,
                             tpd_A_Y_negedge,
                             To_X01(A_ipd) /= '0'),
                      2 => ( B_ipd'LAST_EVENT,
                             tpd_B_Y_posedge,
                             To_X01(B_ipd) /= '1'),
                      3 => ( B_ipd'LAST_EVENT,
                             tpd_B_Y_negedge,
                             To_X01(B_ipd) /= '0'),
                      4 => ( C_ipd'LAST_EVENT,
                             tpd_C_Y_posedge,
                             To_X01(C_ipd) /= '1'),
                      5 => ( C_ipd'LAST_EVENT,
                             tpd_C_Y_negedge,
                             To_X01(C_ipd) /= '0')),
               GlitchData => Y_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );


END PROCESS;

end behavioral;


