      VARIABLE PPN_zd : std_ulogic;

      -- path delay section variables
      VARIABLE PPN_GlitchData : VitalGlitchDataType;

      BEGIN
          -- Functionality section
          n0_var := VitalMUX2(A_ipd, S_ipd, M0_ipd);
          n1_var := VitalMUX2(A_ipd, S_ipd, M1_ipd);
          PPN_zd := VitalMUX2(n0_var, n1_var, X2_ipd);


          -- Path delay section
