               OutSignal     => PPN,
               OutSignalName => "PPN",
               OutTemp => PPN_zd,
               Paths => (
                      0 => ( A_ipd'LAST_EVENT,
                             tpd_A_PPN,
                             TRUE),
                      1 => ( M0_ipd'LAST_EVENT,
                             tpd_M0_PPN_posedge,
                             To_X01(M0_ipd) /= '1'),
                      2 => ( M0_ipd'LAST_EVENT,
                             tpd_M0_PPN_negedge,
                             To_X01(M0_ipd) /= '0'),
                      3 => ( M1_ipd'LAST_EVENT,
                             tpd_M1_PPN_posedge,
                             To_X01(M1_ipd) /= '1'),
                      4 => ( M1_ipd'LAST_EVENT,
                             tpd_M1_PPN_negedge,
                             To_X01(M1_ipd) /= '0'),
                      5 => ( S_ipd'LAST_EVENT,
                             tpd_S_PPN,
                             TRUE),
                      6 => ( X2_ipd'LAST_EVENT,
                             tpd_X2_PPN_posedge,
                             To_X01(X2_ipd) /= '1'),
                      7 => ( X2_ipd'LAST_EVENT,
                             tpd_X2_PPN_negedge,
                             To_X01(X2_ipd) /= '0')),
               GlitchData => PPN_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );


END PROCESS;

end behavioral;


