             tsetup_D_CKN_posedge_negedge : VitalDelayType := 0.10625 ns;
             tsetup_D_CKN_negedge_negedge : VitalDelayType := 0.13125 ns;
             thold_D_CKN_posedge_negedge : VitalDelayType := -0.0125002 ns;
