             tsetup_SI_CK_posedge_posedge : VitalDelayType := 0.0875001 ns;
             tsetup_SI_CK_negedge_posedge : VitalDelayType := 0.0750001 ns;
             thold_SI_CK_posedge_posedge : VitalDelayType := -0.0562502 ns;
             thold_SI_CK_negedge_posedge : VitalDelayType := -0.025 ns;
             tsetup_SE_CK_posedge_posedge : VitalDelayType := 0.0874998 ns;
             tsetup_SE_CK_negedge_posedge : VitalDelayType := 0.10625 ns;
             thold_SE_CK_posedge_posedge : VitalDelayType := -0.0374999 ns;
             thold_SE_CK_negedge_posedge : VitalDelayType := -0.0125002 ns;
             tsetup_RN_CK_posedge_posedge : VitalDelayType := 0.20625 ns;
             tsetup_RN_CK_negedge_posedge : VitalDelayType := 0.125 ns;
             thold_RN_CK_posedge_posedge : VitalDelayType := -0.16875 ns;
             thold_RN_CK_negedge_posedge : VitalDelayType := -0.0749999 ns;
             tsetup_E_CK_posedge_posedge : VitalDelayType := 0.19375 ns;
             tsetup_E_CK_negedge_posedge : VitalDelayType := 0.13125 ns;
             thold_E_CK_posedge_posedge : VitalDelayType := -0.1 ns;
             thold_E_CK_negedge_posedge : VitalDelayType := -0.0937501 ns;
             tsetup_D_CK_posedge_posedge : VitalDelayType := 0.175 ns;
             tsetup_D_CK_negedge_posedge : VitalDelayType := 0.13125 ns;
             thold_D_CK_posedge_posedge : VitalDelayType := -0.125 ns;
             thold_D_CK_negedge_posedge : VitalDelayType := -0.0812503 ns;
             tpd_CK_Q_posedge : VitalDelayType01 := (0.152633 ns, 0.168249 ns);
