                                Result => n0_vec,
                        PreviousDataIn => PrevData_udp_tlat_n0 );

          EINT := n0_vec(1);

          N0 := VitalINV(EINT);

          ECK_zd := VitalAND2(CK_dly, EINT);

          E_EQ_0 := VitalINV(E_dly);


          -- Path delay section
          VitalPathDelay01(
               OutSignal     => ECK,
               OutSignalName => "ECK",
               OutTemp => ECK_zd,
               Paths => (
                      0 => ( CK_dly'LAST_EVENT,
                             tpd_CK_ECK_negedge,
                             To_X01(CK_dly) /= '1'),
                      1 => ( CK_dly'LAST_EVENT,
                             tpd_CK_ECK_posedge,
                             To_X01(CK_dly) /= '0')),
               GlitchData => ECK_GlitchData,
               Mode  => OnEvent,
               XOn            => XOn,
               MsgOn          => MsgOn,
               MsgSeverity    => WARNING );


