                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

          END IF;


          -- Functionality section
          NOTIFIER := (
                        Tviol_rec_RN_SN_posedge OR
                        Tviol_rec_GN_SN_posedge OR
                        Tviol_RN_GN OR
                        Tviol_D_GN OR
                        PWviol_SN_negedge OR
                        PWviol_RN_negedge OR
                        PWviol_GN_negedge );

          n1_var := VitalINV(GN_dly);
