             thold_SI_CK_posedge_posedge : VitalDelayType := -0.0562499 ns;
             thold_SI_CK_negedge_posedge : VitalDelayType := -0.0187503 ns;
             tsetup_SE_CK_posedge_posedge : VitalDelayType := 0.0875 ns;
             thold_SE_CK_negedge_posedge : VitalDelayType := -0.0125 ns;
             tsetup_SE_CK_negedge_posedge : VitalDelayType := 0.1125 ns;
             thold_SE_CK_posedge_posedge : VitalDelayType := -0.0250001 ns;
             tsetup_E_CK_posedge_posedge : VitalDelayType := 0.14375 ns;
             tsetup_E_CK_negedge_posedge : VitalDelayType := 0.125 ns;
             thold_E_CK_posedge_posedge : VitalDelayType := -0.1125 ns;
             thold_E_CK_negedge_posedge : VitalDelayType := -0.0312499 ns;
