          n13_var := VitalINV(SI_dly);
          D_EQ_1_AN_E_EQ_1_AN_SI_EQ_0 := VitalAND2(n12_var, n13_var);

          SE_EQ_0 := VitalINV(SE_dly);

          n14_var := VitalINV(SE_dly);
          E_EQ_1_AN_SE_EQ_0 := VitalAND2(E_dly, n14_var);

          n15_var := VitalINV(D_dly);
          n16_var := VitalINV(E_dly);
          n17_var := VitalAND2(n15_var, n16_var);
          n18_var := VitalAND2(n17_var, SE_dly);
          n19_var := VitalINV(SI_dly);
          D_EQ_0_AN_E_EQ_0_AN_SE_EQ_1_AN_SI_EQ_0 := VitalAND2(n18_var, n19_var);


          -- Path delay section
          VitalPathDelay01(
               OutSignal     => Q,
               OutSignalName => "Q",
